/* Shared demo reward wallet and redemption catalogue. No real fulfilment. */
'use strict';
const redemptionCategories=[
  {id:'flights',name:'Flights',icon:'globe',art:'hotel',line:'A little closer to your next take-off.'},
  {id:'experiences',name:'Experiences',icon:'compass',art:'dining',line:'Good tables. New stories. Your kind of day.'},
  {id:'drops',name:'Drops',icon:'gift',art:'sound',line:'Limited finds, picked for your everyday.'},
  {id:'vouchers',name:'Vouchers',icon:'wallet',art:'work',line:'Something useful. Something just for you.'}
];
const redemptionCatalogue=[
  {id:'flight500',category:'flights',title:'₹500 towards your next flight',points:5000,kind:'credit',valuePaise:50000,description:'Use points for a demo flight-booking credit. Your next destination can wait for you to choose it.',terms:['Illustrative ₹500 credit towards a domestic flight booking.','A credit is not a ticket or a confirmed reservation.','One per member in this demo. No airline booking is made.']},
  {id:'flight1000',category:'flights',title:'₹1,000 towards a bigger escape',points:10000,kind:'credit',valuePaise:100000,description:'A larger demo credit for the trip you have in mind.',terms:['Illustrative ₹1,000 domestic flight-booking credit.','Fares, routes, and availability are not live.','One per member in this demo. No airline booking is made.']},
  {id:'tasting',category:'experiences',title:'Coffee tasting for two',points:1500,kind:'experience',description:'A slower afternoon, a few new flavours, and someone to share them with.',terms:['Demo request for two guests at a coffee-tasting experience.','Date and venue would be confirmed separately in a live service.','This prototype records interest only; no booking is made.']},
  {id:'table',category:'experiences',title:'A seat at the chef’s table',points:7000,kind:'experience',description:'An intimate tasting-table experience for two, imagined for Eleva members.',terms:['Illustrative experience request for two guests.','Venue, menu, dates, and availability are placeholders.','No table or event reservation is made.']},
  {id:'desk',category:'drops',title:'The builder’s desk kit',points:4000,kind:'drop',stock:32,description:'Considered essentials for your desk, in a limited member drop.',terms:['One simulated kit claim per member.','Delivery is represented by a saved demo address in Gurugram.','No physical product is shipped.']},
  {id:'audio',category:'drops',title:'The studio audio drop',points:6000,kind:'drop',stock:20,description:'A limited audio accessory drop for focused work and your own soundtrack.',terms:['One simulated audio-drop claim per member.','Product details and stock are illustrative.','No physical product is shipped.']},
  {id:'cafe250',category:'vouchers',title:'₹250 café voucher',points:2500,kind:'voucher',valuePaise:25000,description:'Put your points towards a good cup and a little time to yourself.',terms:['Illustrative ₹250 café voucher.','The generated demo code cannot be used with a merchant.','One per member in this demo.']},
  {id:'work500',category:'vouchers',title:'₹500 workspace voucher',points:5000,kind:'voucher',valuePaise:50000,description:'A little room to focus, with a demo workspace voucher.',terms:['Illustrative ₹500 workspace voucher.','The generated demo code cannot be used with a merchant.','One per member in this demo.']}
];
let hubAllocation='100',hubHistoryFilter='All';
function hubInvestmentPoints(){return Math.floor(state.rewards.availablePoints*Number(hubAllocation)/100)}
function existingRedemption(itemId){return state.rewards.redemptions.find(r=>r.itemId===itemId)}
function rewardRedemptionStatus(order){return order.kind==='experience'?'Request received':order.kind==='drop'?'Claim recorded':order.kind==='credit'?'Demo flight credit ready':'Demo voucher ready'}
function redemptionEligibility(itemId){const item=redemptionCatalogue.find(i=>i.id===itemId);if(!item)return'Unknown reward.';if(existingRedemption(itemId))return'You have already redeemed this reward.';if(!Number.isInteger(state.rewards.availablePoints)||state.rewards.availablePoints<item.points)return`You need ${rewardPoints(Math.max(0,item.points-state.rewards.availablePoints))} more available points.`;return null}
function createRewardRedemption(itemId,requestId){
  if(typeof requestId!=='string'||!requestId||state.rewards.redemptions.some(o=>o.requestId===requestId)||redemptionEligibility(itemId))return null;
  const item=redemptionCatalogue.find(i=>i.id===itemId),count=state.rewards.redemptions.length+1;
  const order={id:'ELV-RD-'+String(count).padStart(4,'0'),requestId,itemId:item.id,category:item.category,title:item.title,kind:item.kind,points:item.points,valuePaise:item.valuePaise||null,date:'26 Oct 2026 · Just now',createdAt:Date.now(),status:item.kind==='experience'?'requested':item.kind==='drop'?'claimed':'ready',code:item.kind==='credit'||item.kind==='voucher'?'ELVA-DEMO-'+String(count).padStart(4,'0'):null};
  state.rewards.availablePoints-=item.points;state.rewards.redemptions.unshift(order);save();return order;
}
function hubInvestmentButton(){const points=hubInvestmentPoints();if(!state.rewards.ready)return rewardPrimaryButton();if(canInvestRewards(points))return`<button class="primary-button full" data-action="invest-rewards" data-points="${points}">Invest ${rewardCurrency(points*REWARD_RATE_PAISE)} ${icon('arrowUp',16)}</button>`;return'<button class="primary-button full" disabled>100 available RP needed to invest</button>'}
function rewardSectionHeading(title,subtitle='',extra=''){return `<div class="reward-section-heading"><div><h2>${title}</h2>${subtitle?`<p>${subtitle}</p>`:''}</div>${extra}</div>`}
function rewardCategoryTiles(){return `<nav class="reward-category-rail" aria-label="Where your points work"><button class="reward-category-tile featured" data-action="focus-mutual-funds" aria-label="Explore mutual funds, featured"><span class="reward-category-photo">${art('wealth')}<span>Featured</span></span><strong>Mutual funds</strong><small>Invest your RP ${icon('arrowUp',11)}</small></button>${redemptionCategories.map(c=>`<button class="reward-category-tile" data-action="redemption-category" data-id="${c.id}" aria-label="Explore ${c.name.toLowerCase()}"><span class="reward-category-photo">${art(c.art)}</span><strong>${c.name}</strong><small>Explore rewards ${icon('arrow',11)}</small></button>`).join('')}</nav>`}
function rewardFeaturedInvestment(){const s=rewardSummary(),fund=selectedRewardFund(),points=hubInvestmentPoints();return `<section class="reward-invest-feature" aria-label="Featured mutual fund conversion" id="featured-mutual-funds" tabindex="-1"><div class="reward-invest-story">${art('wealth')}<div class="reward-invest-story-copy"><span class="eyebrow">THE ELEVA WAY</span><h2>From a little extra.<br>To something more.</h2><p>Your everyday rewards.<br>A new part of your portfolio.</p><button class="text-button" data-action="reward-growth">Your investment story ${icon('arrow',14)}</button></div></div><article class="hub-mutual-funds"><div class="spread"><span class="hub-featured-label">${icon('leaf',13)} RP → MUTUAL FUNDS</span><span class="hub-featured-badge">Featured</span></div><h2>Give your points<br>a future.</h2><p class="hub-mf-description">Choose your fund once. Turn available points into a mutual fund investment in one click.</p><div class="hub-mf-value">${rewardCurrency(points*REWARD_RATE_PAISE)}</div><p class="hub-mf-points">from ${rewardPoints(points)} RP · 10 points = ₹1 · demo</p><div class="hub-allocation" aria-label="Choose points to invest">${[['25','25%'],['50','50%'],['100','All available']].map(([v,l])=>`<button data-action="hub-allocation" data-id="${v}" aria-pressed="${hubAllocation===v}" class="${hubAllocation===v?'active':''}">${l}</button>`).join('')}</div><div class="hub-mf-destination"><span>${fund?fund.name:'Choose a demo mutual fund'}</span><button class="text-button" data-action="reward-setup">${fund?'Change':'Set up'} ${icon('chevron',12)}</button></div><p class="hub-mf-fee">Conversion fee ₹0 · Minimum 100 RP · Demo terms</p>${hubInvestmentButton()}<div class="hub-mf-footer"><span>${rewardCurrency(s.investedPaise)} invested from rewards</span><button class="text-button" data-action="reward-how">How it works ${icon('arrow',12)}</button></div></article></section>`}
function rewardRailControls(id){return `<div class="reward-rail-controls"><button data-action="reward-rail" data-id="${id}" data-direction="-1" aria-label="Previous ${id==='reward-life-rail'?'rewards':'privileges'}">${icon('arrow',16)}</button><button data-action="reward-rail" data-id="${id}" data-direction="1" aria-label="Next ${id==='reward-life-rail'?'rewards':'privileges'}">${icon('arrow',16)}</button></div>`}
function rewardLifestyleCards(){return ['tasting','flight500','audio','cafe250'].map(id=>{const item=redemptionCatalogue.find(i=>i.id===id),category=redemptionCategories.find(c=>c.id===item.category),photo=id==='tasting'?'dining':id==='cafe250'?'gallery':category.art;return `<button class="reward-life-card" data-action="redemption-item" data-id="${id}"><span class="reward-life-photo">${art(photo)}<span class="reward-life-price">${rewardPoints(item.points)} RP</span></span><span class="reward-life-copy"><small>${category.name}</small><strong>${item.title}</strong><span>Make it yours ${icon('arrow',14)}</span></span></button>`}).join('')}
const rewardFaqs=[
  ['How do I earn reward points?','Your card spends can earn RP. Earning rates, eligible categories and exclusions depend on final Eleva terms and are not set in this prototype. The balances shown here are illustrative.'],
  ['What can I do with my points?','Choose mutual fund investing, flight credits, experiences, drops or vouchers. Each reward shows its own RP price. All choices draw from the same available balance.'],
  ['How does one-click investing work?','Select a demo mutual fund and consent once. Then choose 25%, 50% or all available RP and tap Invest. The amount and destination are shown before the click. Your order is tracked until units are allotted.'],
  ['When can I use pending points?','Only available points can be used. Pending points stay separate until they become available. This prototype keeps the pending balance fixed and does not simulate transaction settlement.'],
  ['Do reward points expire?','No expiry is applied to the demo balance. Point validity and expiry rules will be specified in the final Eleva rewards terms.'],
  ['Will reward investments increase my card limit?','Reward investments remain unpledged. Converting points does not automatically pledge those investments or change your card limit.'],
  ['Are the rewards and investments live?','This is a private prototype. Funds, NAVs, point prices, credits, experience requests, drops and voucher codes are simulated. No real investment, booking, shipment or merchant redemption takes place.']
];
function rewardInvestmentStory(){const p=rewardPortfolio(),s=rewardSummary();return `<section class="reward-investment-section" id="reward-investment-story" tabindex="-1" aria-label="Your reward investment growth">${rewardSectionHeading('Your investment story.','See what your reward points have become.','<button class="text-button" data-action="reward-performance">Portfolio details '+icon('arrow',14)+'</button>')}<div class="reward-investment-story"><div class="reward-investment-overview"><span class="eyebrow">BUILT FROM YOUR REWARD POINTS</span><p class="rp-value-label">Current investment value</p><div class="rp-current-value">${p.currentPaise===null?'—':`<span>₹</span>${rewardCurrency(p.currentPaise).slice(1)}`}</div><button class="rp-xirr ${p.xirr!==null&&p.xirr<0?'negative':''}" data-action="reward-performance" aria-label="Understand your reward portfolio and XIRR"><strong>${rewardXirrLabel(p.xirr)}</strong><span>XIRR · annualised</span>${icon('info',11)}</button><dl class="reward-investment-breakdown"><div><dt>Invested amount</dt><dd>${rewardCurrency(p.investedPaise)}</dd></div><div><dt>Unrealised ${p.gainPaise!==null&&p.gainPaise<0?'loss':'gain'}</dt><dd class="${p.gainPaise!==null&&p.gainPaise<0?'negative':''}">${p.gainPaise===null?'—':rewardCurrency(p.gainPaise)}</dd></div></dl><p class="reward-investment-date">Demo NAV as of 26 Oct 2026</p>${s.processingPaise?`<p class="reward-investment-pending">${rewardCurrency(s.processingPaise)} awaiting allotment</p>`:''}<button class="primary-button" data-action="focus-mutual-funds">${s.availablePoints>=REWARD_MIN_POINTS?'Invest more reward points':'Explore mutual funds'} ${icon('arrowUp',15)}</button></div><div class="reward-investment-history"><div id="rewards-rp-chart" data-reward-chart>${rewardChartMarkup()}</div><p class="reward-investment-chart-note">Monthly RP converted to mutual funds. Portfolio value includes allotted units only.</p></div></div></section>`}
function rewardHubPage(){const s=rewardSummary(),used=s.convertedPoints+state.rewards.redemptions.reduce((n,r)=>n+r.points,0);return `<div class="rewards-story">${intro('ELEVA REWARDS','Your points. <em>Your possibilities.</em>','A little for now. A little for what’s next.')}
  <section class="reward-balance-hero" aria-label="Reward points balance"><div class="reward-balance-top"><span class="eyebrow">YOUR EVERYDAY, REWARDED</span><button class="text-button" data-action="reward-points">Points summary ${icon('arrow',13)}</button></div><div class="reward-balance-center"><span class="reward-balance-emblem">${mark()}</span><p>You have</p><h2>${rewardPoints(s.availablePoints)} <span>reward points</span></h2><p>More ways to make them yours.</p><button class="reward-balance-invest" data-action="focus-mutual-funds">${s.availablePoints>=REWARD_MIN_POINTS?rewardCurrency(s.availablePaise)+' towards mutual funds':'Explore mutual fund investing'} ${icon('arrowUp',12)}</button></div><div class="reward-balance-stats"><div><strong>${rewardPoints(s.availablePoints+used)}</strong><span>Lifetime earned RP</span></div><div><strong>${rewardPoints(s.pendingPoints)}</strong><span>Pending RP</span></div><button data-action="reward-growth" aria-label="View your reward investment growth"><strong>${rewardCurrency(s.investedPaise)}</strong><span>Invested from RP ${icon('arrowUp',10)}</span></button></div><button class="reward-balance-activity" data-action="reward-activity">Your rewards activity ${icon('arrow',13)}</button></section>
  ${rewardInvestmentStory()}
  <section class="reward-learn-section">${rewardSectionHeading('A little know-how. A lot of possibility.','Get to know your Eleva reward points.')}<div class="reward-learn-grid"><button class="reward-learn-card" data-action="reward-earn" aria-label="How to earn Eleva reward points"><span class="reward-learn-photo">${art('work')}</span><span class="reward-learn-arrow">${icon('arrowUp',20)}</span><span class="reward-learn-copy"><small>01 / EARN POINTS</small><strong>Everyday spends.<br>Extra possibilities.</strong><span>How your RP add up</span></span></button><button class="reward-learn-card" data-action="reward-use" aria-label="Ways to use Eleva reward points"><span class="reward-learn-photo">${art('gallery')}</span><span class="reward-learn-arrow">${icon('arrowUp',20)}</span><span class="reward-learn-copy"><small>02 / USE POINTS</small><strong>Your points.<br>Your kind of reward.</strong><span>Find your next something</span></span></button></div></section>
  <section class="reward-category-section">${rewardSectionHeading('Where your points work.','Five ways to make the most of your RP.','<span class="reward-swipe-hint">Swipe to explore '+icon('arrow',13)+'</span>')}${rewardCategoryTiles()}</section>
  ${rewardSectionHeading('A reward for future you.','Our signature way to turn rewards into more.')}${rewardFeaturedInvestment()}
  <section class="reward-lifestyle-section">${rewardSectionHeading('Points for a life well lived.','A new experience. A small escape. Something just for you.',rewardRailControls('reward-life-rail'))}<div class="reward-content-rail" id="reward-life-rail" aria-label="Featured reward catalogue">${rewardLifestyleCards()}</div></section>
  <section class="reward-privileges">${rewardSectionHeading('A little extra, from Eleva.','Member privileges beyond your points.','<button class="text-button" data-action="go-discover">Discover all '+icon('arrow',14)+'</button>')}<div class="reward-perk-rail" aria-label="Eleva member privileges">${['stay','dine','sound'].map(id=>{const o=offers.find(o=>o.id===id);return `<button class="reward-perk-card" data-action="offer" data-id="${id}"><span class="reward-perk-photo">${art(o.art)}<span>MEMBER PRIVILEGE</span></span><small>${o.brand}</small><strong>${o.benefit}</strong><span>Explore benefit ${icon('arrow',13)}</span></button>`}).join('')}</div></section>
  <section class="panel hub-activity" id="reward-activity" tabindex="-1"><div class="reward-history-heading"><div><h2>Your rewards activity</h2><p class="small muted">Every investment, credit, claim and voucher.</p></div><div class="filters" aria-label="Filter rewards activity">${['All','Mutual funds','Other rewards'].map(f=>`<button class="filter ${hubHistoryFilter===f?'active':''}" data-action="hub-history-filter" data-id="${f}">${f}</button>`).join('')}</div></div><div id="hub-activity-list">${hubActivityMarkup()}</div></section>
  <section class="reward-faq-section">${rewardSectionHeading('A few good answers.','Everything else about your points.')}<div class="reward-faq-list">${rewardFaqs.map(([q,a])=>`<details><summary>${q}${icon('plus',16)}</summary><p>${a}</p></details>`).join('')}</div></section>
  <div class="reward-story-footer"><span>${mark()}</span><h2>Make room for<br><em>what’s next.</em></h2><p>YOUR REWARDS. YOUR WAY.</p></div><p class="prototype-footnote">Illustrative rewards and terms. Mutual fund conversion value applies only to that option, not every reward. Reward investments remain separate from the portfolio backing your card.</p></div>`}
function scrollToRewardSection(id){closeDialog();const target=document.getElementById(id);if(target){target.scrollIntoView({behavior:window.matchMedia?.('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'});target.focus({preventScroll:true})}}
function scrollRewardRail(el){const rail=document.getElementById(el.dataset.id);if(rail)rail.scrollBy({left:rail.clientWidth*.8*Number(el.dataset.direction),behavior:window.matchMedia?.('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'})}
function rewardEarnDialog(){openDialog('A little more from everyday.',`<div class="product-preview-photo">${art('work')}</div><div class="spacer"></div><div class="eyebrow">GET TO KNOW YOUR RP</div><h3>Spend. Earn.<br>Choose your next move.</h3><div class="reward-how-step"><span>01</span><div><h4>Use your Eleva card</h4><p>Eligible everyday spends can earn reward points. Category rates and exclusions will be defined in the final card terms.</p></div></div><div class="reward-how-step"><span>02</span><div><h4>Know what’s available</h4><p>Available RP are ready to use. Pending RP stay separate and cannot be redeemed yet.</p></div></div><div class="reward-how-step"><span>03</span><div><h4>Make them yours</h4><p>Invest in mutual funds or choose flights, experiences, drops and vouchers. Each choice shows the RP you need before you commit.</p></div></div><p class="amount-note">The demo begins with 8,400 available RP and 1,260 pending RP. No earning rate or actual points accrual is simulated.</p>`,`<button class="primary-button" data-action="reward-use">Explore ways to use points ${icon('arrow',15)}</button><button class="secondary-button" data-action="close">Done</button>`)}
function rewardUseDialog(){openDialog('Your points. Your kind of reward.',`<div class="eyebrow">FIVE POSSIBILITIES. ONE BALANCE.</div><h3>Pick what matters<br>to you.</h3><p class="lead">${rewardPoints(state.rewards.availablePoints)} RP available. Every reward shows its cost, with pending points kept separate.</p><div class="reward-use-options"><button class="hub-catalogue-item" data-action="focus-mutual-funds"><span><strong>Mutual funds <span class="soft-badge">Featured</span></strong><small>Choose once. Invest in a click.</small></span>${icon('arrow',16)}</button>${redemptionCategories.map(c=>`<button class="hub-catalogue-item" data-action="redemption-category" data-id="${c.id}"><span><strong>${c.name}</strong><small>${c.line}</small></span>${icon('arrow',16)}</button>`).join('')}</div><p class="amount-note">Rewards are illustrative. No real investment or fulfilment takes place.</p>`,`<button class="secondary-button" data-action="close">Back to rewards</button>`)}
function hubActivityMarkup(){let list=[...state.rewards.orders.map(o=>({...o,activityType:'investment'})),...state.rewards.redemptions.map(o=>({...o,activityType:'redemption'}))];list.sort((a,b)=>(b.createdAt||Date.parse(b.date.replace(' · Just now',''))||0)-(a.createdAt||Date.parse(a.date.replace(' · Just now',''))||0));if(hubHistoryFilter==='Mutual funds')list=list.filter(o=>o.activityType==='investment');if(hubHistoryFilter==='Other rewards')list=list.filter(o=>o.activityType==='redemption');return list.length?list.map(o=>o.activityType==='investment'?rewardOrderRow(o):`<button class="reward-order-row" data-action="redemption-order" data-id="${o.id}"><span class="reward-order-icon">${icon(redemptionCategories.find(c=>c.id===o.category).icon,19)}</span><span class="reward-order-name"><strong>${o.title}</strong><small>${redemptionCategories.find(c=>c.id===o.category).name} · ${o.date}</small></span><span class="reward-order-right"><strong>${rewardPoints(o.points)} RP</strong><span class="reward-status allotted">${rewardRedemptionStatus(o)}</span></span>${icon('chevron',15)}</button>`).join(''):'<div class="reward-empty">'+icon('gift',27)+'<h3>Your next reward starts here.</h3><p>Choose a reward to see your redemption activity here.</p></div>'}
function redemptionCategoryDialog(id){const category=redemptionCategories.find(c=>c.id===id);if(!category)return;openDialog(category.name,`<div class="modal-image"><div class="offer-art">${art(category.art)}</div></div><div class="eyebrow">YOUR POINTS. YOUR CHOICE.</div><h3>${category.line}</h3><p class="lead">${rewardPoints(state.rewards.availablePoints)} RP available · Illustrative rewards</p><div class="hub-catalogue-list">${redemptionCatalogue.filter(i=>i.category===id).map(item=>{const order=existingRedemption(item.id),short=Math.max(0,item.points-state.rewards.availablePoints);return`<button class="hub-catalogue-item" data-action="redemption-item" data-id="${item.id}"><span><strong>${item.title}</strong><small>${rewardPoints(item.points)} RP${item.kind==='drop'?' · '+(item.stock-(order?1:0))+' demo pieces remaining':''}</small><span class="hub-catalogue-state">${order?'Already redeemed · view details':short?rewardPoints(short)+' more RP needed':'Available with your points'}</span></span>${icon('chevron',16)}</button>`}).join('')}</div><p class="prototype-footnote">Sample rewards only. No actual booking, shipping, or merchant redemption takes place.</p>`,`<button class="secondary-button" data-action="finish-rewards">Back to all rewards</button>`)}
function redemptionItemDialog(id){const item=redemptionCatalogue.find(i=>i.id===id);if(!item)return;const category=redemptionCategories.find(c=>c.id===item.category),order=existingRedemption(item.id),error=redemptionEligibility(id);openDialog(category.name,`<div class="modal-image"><div class="offer-art">${art(category.art)}</div></div><div class="eyebrow">${category.name} · DEMO REWARD</div><h3>${item.title}</h3><p class="lead">${item.description}</p><div class="hub-item-points">${rewardPoints(item.points)} <span>RP</span></div><div class="receipt"><div class="data-row"><span>Available points</span><strong>${rewardPoints(state.rewards.availablePoints)} RP</strong></div><div class="data-row"><span>${order?'Already used for this reward':state.rewards.availablePoints<item.points?'Additional RP needed':'Points after redemption'}</span><strong>${order?rewardPoints(order.points):rewardPoints(Math.abs(state.rewards.availablePoints-item.points))} RP</strong></div><div class="data-row"><span>Delivery in this prototype</span><strong>${item.kind==='drop'?'Saved demo address · Gurugram':item.kind==='experience'?'Demo request only':'Code in My rewards'}</strong></div></div><hr class="divider"><h4>The finer details</h4><ul>${item.terms.map(t=>`<li>${t}</li>`).join('')}</ul>${error&&!order?`<div class="callout warning">${icon('info',17)}${error} Pending points cannot be used.</div>`:''}`,`${order?`<button class="primary-button" data-action="redemption-order" data-id="${order.id}">View my redemption ${icon('arrow',15)}</button>`:`<button class="primary-button" data-action="review-redemption" data-id="${item.id}" ${error?'disabled':''}>${error?'Not enough available RP':'Review redemption'} ${!error?icon('arrow',15):''}</button>`}<button class="secondary-button" data-action="redemption-category" data-id="${category.id}">Back to ${category.name.toLowerCase()}</button>`)}
function reviewRewardRedemption(id){const item=redemptionCatalogue.find(i=>i.id===id);if(!item||redemptionEligibility(id))return;dialogData={type:'reward-redemption',itemId:id,requestId:'request-'+Date.now()+'-'+state.rewards.redemptions.length};openDialog('Review your redemption',`<div class="eyebrow">${redemptionCategories.find(c=>c.id===item.category).name} · DEMO REWARD</div><h3>${item.title}</h3><p class="lead">${item.kind==='experience'?'This records a demo request. Availability is not confirmed.':item.kind==='drop'?'This records a demo claim. No physical item will be shipped.':'This generates a demo code. It cannot be used with a merchant.'}</p><div class="receipt"><div class="data-row"><span>Points to use</span><strong>${rewardPoints(item.points)} RP</strong></div><div class="data-row"><span>Points remaining</span><strong>${rewardPoints(state.rewards.availablePoints-item.points)} RP</strong></div><div class="data-row"><span>Pending points · excluded</span><strong>${rewardPoints(state.rewards.pendingPoints)} RP</strong></div><div class="data-row"><span>Additional payment</span><strong>₹0 · demo</strong></div></div><p class="amount-note">These points will no longer be available for mutual funds or another reward. One redemption per catalogue item in this demo.</p>`,`<button class="primary-button" data-action="confirm-redemption">Redeem ${rewardPoints(item.points)} RP ${icon('check',16)}</button><button class="secondary-button" data-action="redemption-item" data-id="${id}">Back to reward details</button>`)}
function confirmRewardRedemption(){if(dialogData?.type!=='reward-redemption')return;const {itemId,requestId}=dialogData;dialogData=null;const order=createRewardRedemption(itemId,requestId);if(!order){toast('This reward can’t be redeemed with the current available balance.');return}render();redemptionReceiptDialog(order.id,true)}
function redemptionReceiptDialog(id,fresh=false){const order=state.rewards.redemptions.find(o=>o.id===id);if(!order)return;openDialog(fresh?'Your reward, recorded.':'Your redemption',`<div class="success"><div class="success-icon">${icon(order.kind==='experience'?'compass':order.kind==='drop'?'gift':'check',28)}</div><h3>${rewardRedemptionStatus(order)}</h3><p>${order.title}</p><div class="hub-receipt-points">${rewardPoints(order.points)} RP</div><p>${rewardPoints(state.rewards.availablePoints)} RP still available to use</p></div>${order.code?`<div class="code-box">${order.code}</div><p class="small muted">This code is illustrative and cannot be used with a merchant.</p>`:''}<div class="receipt"><div class="data-row"><span>Reference</span><strong>${order.id}</strong></div><div class="data-row"><span>Status</span><strong>${rewardRedemptionStatus(order)}</strong></div><div class="data-row"><span>Reward</span><strong>${redemptionCategories.find(c=>c.id===order.category).name}</strong></div><div class="data-row"><span>Points used</span><strong>${rewardPoints(order.points)} RP</strong></div></div><div class="callout" style="margin-top:20px">${icon('info',17)}${order.kind==='experience'?'Your demo request is recorded. No venue or event reservation has been confirmed.':order.kind==='drop'?'Your demo claim is recorded. No real product is being shipped.':order.kind==='voucher'?'Your demo voucher is recorded. This code cannot be used with a merchant.':'Your demo flight credit is recorded. No actual ticket or booking is issued.'}</div>`,`${order.code?`<button class="primary-button" data-action="copy-redemption-code" data-id="${order.id}">${icon('copy',15)}Copy demo code</button>`:''}<button class="${order.code?'secondary-button':'primary-button'}" data-action="finish-rewards">View all rewards ${icon('arrow',15)}</button><button class="secondary-button" data-action="close">Done</button>`)}
async function copyRewardRedemptionCode(id){const order=state.rewards.redemptions.find(o=>o.id===id);if(!order?.code)return;try{await navigator.clipboard.writeText(order.code);toast('Demo code copied.')}catch{toast('Demo code: '+order.code)}}
